css:
/* Nest receipt — 80 mm thermal roll (72 mm printable). Thermal heads print black only and dither greys,
   so hierarchy comes from size, weight and rules, never from tint. IBM Plex is the apps' own typeface,
   served from /assets/nest_restaurant/fonts/ (latin + arabic subsets, matched by unicode-range). */
@font-face { font-family: "Nest Receipt"; font-weight: 400; font-display: swap; src: url("/assets/nest_restaurant/fonts/ibm-plex-sans-latin-400-normal.woff2") format("woff2"); unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }
@font-face { font-family: "Nest Receipt"; font-weight: 600; font-display: swap; src: url("/assets/nest_restaurant/fonts/ibm-plex-sans-latin-600-normal.woff2") format("woff2"); unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }
@font-face { font-family: "Nest Receipt"; font-weight: 700; font-display: swap; src: url("/assets/nest_restaurant/fonts/ibm-plex-sans-latin-700-normal.woff2") format("woff2"); unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }
@font-face { font-family: "Nest Receipt"; font-weight: 400; font-display: swap; src: url("/assets/nest_restaurant/fonts/ibm-plex-sans-arabic-arabic-400-normal.woff2") format("woff2"); unicode-range: U+0600-06FF, U+0750-077F, U+0870-088E, U+0890-0891, U+0897-08E1, U+08E3-08FF, U+200C-200E, U+2010-2011, U+204F, U+2E41, U+FB50-FDFF, U+FE70-FE74, U+FE76-FEFC; }
@font-face { font-family: "Nest Receipt"; font-weight: 600; font-display: swap; src: url("/assets/nest_restaurant/fonts/ibm-plex-sans-arabic-arabic-600-normal.woff2") format("woff2"); unicode-range: U+0600-06FF, U+0750-077F, U+0870-088E, U+0890-0891, U+0897-08E1, U+08E3-08FF, U+200C-200E, U+2010-2011, U+204F, U+2E41, U+FB50-FDFF, U+FE70-FE74, U+FE76-FEFC; }
@font-face { font-family: "Nest Receipt"; font-weight: 700; font-display: swap; src: url("/assets/nest_restaurant/fonts/ibm-plex-sans-arabic-arabic-700-normal.woff2") format("woff2"); unicode-range: U+0600-06FF, U+0750-077F, U+0870-088E, U+0890-0891, U+0897-08E1, U+08E3-08FF, U+200C-200E, U+2010-2011, U+204F, U+2E41, U+FB50-FDFF, U+FE70-FE74, U+FE76-FEFC; }

/* Frappe's print shell: narrow it to the roll and drop the letter head (the receipt has its own header). */
.print-format { width: 80mm !important; max-width: 80mm !important; min-height: 0 !important; margin: 0 auto !important; padding: 5mm 4mm 6mm !important; }
.print-format .letter-head, .print-format .letter-head-footer { display: none !important; }

.nr {
	--ink: #1e1d1d;
	--rule: 1px dashed var(--ink);
	font-family: "Nest Receipt", "IBM Plex Sans", "IBM Plex Sans Arabic", "Segoe UI", Tahoma, sans-serif;
	font-size: 9pt;
	line-height: 1.4;
	color: var(--ink);
	font-variant-numeric: tabular-nums;
	text-align: start;
}
.nr * { box-sizing: border-box; }
.nr p, .nr h1, .nr dl, .nr dd { margin: 0; }
.nr bdi { unicode-bidi: isolate; }

/* Header: logo, company, contact */
.nr-head { text-align: center; padding-block-end: 3mm; }
.nr-logo { display: block; max-width: 46mm; max-height: 24mm; margin: 0 auto 2.5mm; object-fit: contain; }
.nr-co { font-size: 11pt; font-weight: 700; line-height: 1.25; }
.nr-addr { font-size: 7.5pt; margin-block-start: 1mm; }
.nr-contact { font-size: 7.5pt; margin-block-start: 0.5mm; display: flex; justify-content: center; flex-wrap: wrap; column-gap: 3mm; }

/* Title band: solid ink bar is the one strong shape on the page, like the till's selected tab */
.nr-title { border-block: 1.5px solid var(--ink); padding-block: 2mm; text-align: center; }
.nr-title h1 { font-size: 12pt; font-weight: 700; letter-spacing: 0.02em; line-height: 1.2; }
.nr-no { display: block; font-size: 8pt; font-weight: 600; margin-block-start: 0.5mm; }
.nr-stamp { display: inline-block; margin-block-start: 1.5mm; padding: 0.5mm 2.5mm; border: 1.5px solid var(--ink); border-radius: 999px; font-size: 8pt; font-weight: 700; text-transform: uppercase; }

/* Meta: two columns of label / value */
.nr-meta { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5mm 3mm; padding-block: 2.5mm; border-block-end: var(--rule); }
.nr-meta > div { min-width: 0; }
.nr-meta .nr-wide { grid-column: 1 / -1; }
.nr-meta dt { font-size: 7pt; text-transform: uppercase; letter-spacing: 0.04em; }
.nr-meta dd { font-weight: 600; overflow-wrap: anywhere; }

/* Items */
.nr-items { width: 100%; border-collapse: collapse; margin-block-start: 1.5mm; }
.nr-items th, .nr-items td { border: 0 !important; padding: 0; vertical-align: top; background: none !important; }
.nr-items th { font-size: 7pt; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; padding-block: 1mm; border-block-end: var(--rule) !important; }
.nr-items td { padding-block: 1.5mm; }
.nr-items tr { break-inside: avoid; page-break-inside: avoid; }
.nr-desc { text-align: start; padding-inline-end: 2mm !important; }
.nr-num { text-align: end; white-space: nowrap; font-weight: 600; }
.nr-name { display: block; font-weight: 600; overflow-wrap: anywhere; }
.nr-sub { display: block; font-size: 7.5pt; }
.nr-count { font-size: 7.5pt; padding-block: 1.5mm 2mm; border-block: var(--rule); }

/* Sums and payments */
.nr-sums { padding-block: 2mm; }
.nr-sums > div { display: flex; justify-content: space-between; gap: 3mm; padding-block: 0.4mm; }
.nr-sums dt { min-width: 0; overflow-wrap: anywhere; }
.nr-sums dd { white-space: nowrap; }
.nr-grand { border-block-start: 1.5px solid var(--ink); margin-block-start: 1.5mm; padding-block-start: 1.5mm !important; font-size: 13pt; font-weight: 700; line-height: 1.2; }
.nr-pay { border-block-start: var(--rule); }
.nr-strong { font-weight: 700; }

/* Footer */
.nr-foot { border-block-start: var(--rule); padding-block-start: 3mm; text-align: center; }
.nr-note { font-size: 8.5pt; font-weight: 600; white-space: pre-line; }
.nr-ref { font-size: 7pt; margin-block-start: 2mm; letter-spacing: 0.04em; }

@media print {
	@page { margin: 0; }
	.print-format { padding: 3mm 3mm 8mm !important; }
}

html:
{#- Nest receipt (80 mm thermal). Source of truth for the "Nest Restaurant Receipt" print format; tools/gen_print.py
    fills the double-underscore placeholders per app. Renders POS Invoice and Sales Invoice (direct mode) alike.
    Frappe's print Jinja does not autoescape, so every user-entered value goes through |e. -#}
{%- set settings = "Nest Restaurant Settings" -%}
{%- set co = frappe.db.get_value("Company", doc.company, ["company_logo", "tax_id", "phone_no", "email"], as_dict=1) or {} -%}
{%- set logo = frappe.db.get_single_value(settings, "receipt_logo") or co.company_logo -%}
{%- set footer = frappe.db.get_single_value(settings, "receipt_footer") -%}
{%- set rtl = frappe.lang in ("ar", "fa", "he", "ur") -%}
{%- set session = doc.get("nest_rest_session") -%}
{%- set register = frappe.db.get_value("Nest Restaurant Register Session", session, "register") if session else None -%}
{%- set cashier = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner -%}
{%- set total = doc.rounded_total if (doc.rounded_total and not doc.disable_rounded_total) else doc.grand_total -%}
{%- set total_field = "rounded_total" if (doc.rounded_total and not doc.disable_rounded_total) else "grand_total" -%}
{%- set money = frappe.utils.fmt_money -%}
{%- set item_count = doc.items | length -%}
{%- set qty_total = doc.items | sum(attribute="qty") -%}
<div class="nr" dir="{{ 'rtl' if rtl else 'ltr' }}" lang="{{ frappe.lang }}">
	<header class="nr-head">
		{%- if logo %}
		<img class="nr-logo" src="{{ logo | e }}" alt="{{ doc.company | e }}">
		{%- endif %}
		<p class="nr-co"><bdi>{{ doc.company | e }}</bdi></p>
		{%- if doc.company_address_display %}
		<div class="nr-addr"><bdi>{{ doc.company_address_display }}</bdi></div>
		{%- endif %}
		{%- if co.phone_no or doc.company_tax_id or co.tax_id %}
		<p class="nr-contact">
			{%- if co.phone_no %}<span>{{ _("Tel") }} <bdi>{{ co.phone_no | e }}</bdi></span>{% endif -%}
			{%- if doc.company_tax_id or co.tax_id %}<span>{{ _("Tax ID") }} <bdi>{{ (doc.company_tax_id or co.tax_id) | e }}</bdi></span>{% endif -%}
		</p>
		{%- endif %}
	</header>

	<section class="nr-title">
		<h1>{{ _("Return receipt") if doc.is_return else _("Receipt") }}</h1>
		<bdi class="nr-no">{{ doc.name }}</bdi>
		{%- if doc.docstatus == 0 %}
		<p class="nr-stamp">{{ _("Draft — not a valid receipt") }}</p>
		{%- elif doc.docstatus == 2 %}
		<p class="nr-stamp">{{ _("Cancelled") }}</p>
		{%- endif %}
	</section>

	<dl class="nr-meta">
		<div><dt>{{ _("Date") }}</dt><dd><bdi>{{ doc.get_formatted("posting_date") }}</bdi></dd></div>
		<div><dt>{{ _("Time") }}</dt><dd><bdi>{{ (doc.posting_time | string).split(".")[0].rsplit(":", 1)[0] }}</bdi></dd></div>
		<div><dt>{{ _("Cashier") }}</dt><dd><bdi>{{ cashier | e }}</bdi></dd></div>
		{%- if register %}
		<div><dt>{{ _("Register") }}</dt><dd><bdi>{{ register | e }}</bdi></dd></div>
		{%- endif %}
		<div class="nr-wide"><dt>{{ _("Customer") }}</dt><dd><bdi>{{ (doc.customer_name or doc.customer) | e }}</bdi></dd></div>
		{%- if doc.is_return and doc.return_against %}
		<div class="nr-wide"><dt>{{ _("Against") }}</dt><dd><bdi>{{ doc.return_against }}</bdi></dd></div>
		{%- endif %}
	</dl>

	<table class="nr-items">
		<thead>
			<tr><th class="nr-desc">{{ _("Item") }}</th><th class="nr-num">{{ _("Amount") }}</th></tr>
		</thead>
		<tbody>
			{%- for it in doc.items %}
			<tr>
				<td class="nr-desc">
					<span class="nr-name"><bdi>{{ it.item_name | e }}</bdi></span>
					<span class="nr-sub"><bdi>{{ "%g" | format(it.qty) }} {{ it.uom | e }} × {{ money(it.rate) }}</bdi>
						{%- if it.discount_percentage %} · <bdi>−{{ "%g" | format(it.discount_percentage) }}%</bdi>{% endif -%}
					</span>
					{%- if it.serial_no %}<span class="nr-sub">{{ _("Serial") }} <bdi>{{ it.serial_no | replace("\n", ", ") | e }}</bdi></span>{% endif %}
				</td>
				<td class="nr-num"><bdi>{{ money(it.amount) }}</bdi></td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>
	<p class="nr-count">
		{%- if item_count == 1 %}{{ _("1 item · quantity {0}").format("%g" | format(qty_total)) }}
		{%- else %}{{ _("{0} items · quantity {1}").format(item_count, "%g" | format(qty_total)) }}{% endif -%}
	</p>

	<dl class="nr-sums">
		<div><dt>{{ _("Subtotal") }}</dt><dd><bdi>{{ money(doc.total) }}</bdi></dd></div>
		{%- if doc.discount_amount %}
		<div><dt>{{ _("Discount") }}</dt><dd><bdi>−{{ money(doc.discount_amount) }}</bdi></dd></div>
		{%- endif %}
		{%- for t in doc.taxes if t.tax_amount %}
		<div><dt><bdi>{{ t.description | e }}</bdi></dt><dd><bdi>{{ money(t.tax_amount) }}</bdi></dd></div>
		{%- endfor %}
		{%- if doc.rounding_adjustment and total_field == "rounded_total" %}
		<div><dt>{{ _("Rounding") }}</dt><dd><bdi>{{ money(doc.rounding_adjustment) }}</bdi></dd></div>
		{%- endif %}
		<div class="nr-grand"><dt>{{ _("Refund total") if doc.is_return else _("Total") }}</dt><dd><bdi>{{ doc.get_formatted(total_field) }}</bdi></dd></div>
	</dl>

	{%- set paid_rows = doc.payments | selectattr("amount") | list %}
	{%- if paid_rows or doc.change_amount %}
	<dl class="nr-sums nr-pay">
		{%- for p in paid_rows %}
		<div><dt><bdi>{{ p.mode_of_payment | e }}</bdi></dt><dd><bdi>{{ money(p.amount) }}</bdi></dd></div>
		{%- endfor %}
		{%- if doc.change_amount %}
		<div class="nr-strong"><dt>{{ _("Change") }}</dt><dd><bdi>{{ money(doc.change_amount) }}</bdi></dd></div>
		{%- endif %}
		{%- if doc.outstanding_amount and doc.outstanding_amount > 0 and not doc.is_return %}
		<div class="nr-strong"><dt>{{ _("Balance due") }}</dt><dd><bdi>{{ money(doc.outstanding_amount) }}</bdi></dd></div>
		{%- endif %}
	</dl>
	{%- endif %}

	<footer class="nr-foot">
		<p class="nr-note"><bdi>{{ (footer or _("Thank you for your visit")) | e }}</bdi></p>
		<p class="nr-ref"><bdi>{{ doc.name }}</bdi></p>
	</footer>
</div>
